  &reftitle.examples;

   Функция mb_strpos возвращает позицию в символах, а не в байтах


<?php
// "🐘" занимает 4 байта, но это 1 символ; "é" занимает 2 байта, но это 1 символ
$str = "🐘H🐘é";

var_dump(mb_strpos($str, "é"));  // символ 3, а не байт 9
var_dump(mb_strpos($str, "🐘", 1)); // символ 2, первый "🐘" пропускается
?>


   &example.outputs;


